<?php
declare(strict_types=1);
require_once __DIR__.'/../../../public/api/admin/ThumbnailIntegrityService.php';require_once __DIR__.'/../../../public/api/admin/DatasetPackage.php';
use FreeTV\Admin\DatasetPackage;use FreeTV\Admin\ThumbnailIntegrityService;use PHPUnit\Framework\TestCase;
final class ThumbnailIntegrityServiceTest extends TestCase
{
 private string $root;protected function setUp():void{$this->root=sys_get_temp_dir().'/freetv-thumb-integrity-'.bin2hex(random_bytes(8));mkdir($this->root); }protected function tearDown():void{DatasetPackage::removeTree($this->root);}
 public function testAuditIsDeterministicCompleteAndReadOnly():void
 {
  foreach(['tt100.jpg'=>'present','tt300.jpg'=>'orphan','tt000000.jpg'=>'placeholder','index.html'=>'x','random.jpg'=>'x','tt400.jpeg'=>'x','TT500.jpg'=>'x'] as $f=>$b)file_put_contents($this->root.'/'.$f,$b);mkdir($this->root.'/tt600.jpg');$target=$this->root.'/target';file_put_contents($target,'x');symlink($target,$this->root.'/tt700.jpg');
  $rows=[['id'=>5,'playlist_id'=>2,'playlist_filename'=>'b.json','playlist_title'=>'B','identifier'=>'z','title'=>'Z','category'=>'C','imdb'=>'tt100'],['id'=>2,'playlist_id'=>1,'playlist_filename'=>'a.json','playlist_title'=>'A','identifier'=>'a','title'=>'A','category'=>'D','imdb'=>'tt200'],['id'=>1,'playlist_id'=>1,'playlist_filename'=>'a.json','playlist_title'=>'A','identifier'=>'b','title'=>'B','category'=>'D','imdb'=>'tt100'],['id'=>8,'playlist_id'=>3,'playlist_filename'=>'c.json','playlist_title'=>'C','identifier'=>'i','title'=>'Invalid','category'=>'X','imdb'=>'bad'],['id'=>9,'playlist_id'=>3,'playlist_filename'=>'c.json','playlist_title'=>'C','identifier'=>'j','title'=>'Invalid2','category'=>'X','imdb'=>' bad '],['id'=>10,'playlist_id'=>1,'imdb'=>null],['id'=>11,'playlist_id'=>1,'imdb'=>' '],['id'=>12,'playlist_id'=>1,'imdb'=>'tt000000']];$beforeRows=serialize($rows);$before=$this->tree();$calls=0;$result=(new ThumbnailIntegrityService($this->root,static function()use(&$calls,$rows){$calls++;return $rows;}))->audit();
  self::assertSame(['total_distinct_valid_imdb_references'=>2,'total_thumbnail_jpg_files_considered'=>2,'present'=>1,'missing'=>1,'orphaned'=>1,'invalid_database_imdb_values'=>1,'invalid_database_imdb_rows'=>2],$result['summary']);self::assertSame(['tt100'],array_column($result['present'],'imdb'));self::assertSame(['tt200'],array_column($result['missing'],'imdb'));self::assertSame(['tt300'],array_column($result['orphaned'],'imdb'));self::assertSame(['bad'],array_column($result['invalid_database_imdb'],'value'));self::assertSame(['show_count'=>2,'playlist_count'=>2],$result['present'][0]['usage']);self::assertSame('a',$result['missing'][0]['representative_show']['identifier']);self::assertSame(1,$calls);self::assertSame($beforeRows,serialize($rows));self::assertSame($before,$this->tree());
 }
 public function testInvalidLoaderAndUnavailableDirectoryFail():void{try{(new ThumbnailIntegrityService($this->root,static fn()=>null))->audit();self::fail('invalid loader');}catch(RuntimeException){}DatasetPackage::removeTree($this->root);$this->expectException(RuntimeException::class);(new ThumbnailIntegrityService($this->root,static fn()=>[]))->audit();}
 public function testInvalidRowsFail():void{$this->expectException(RuntimeException::class);(new ThumbnailIntegrityService($this->root,static fn()=>['bad']))->audit();}
 private function tree():array{$out=[];$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($this->root,FilesystemIterator::SKIP_DOTS));foreach($it as $f)$out[substr($f->getPathname(),strlen($this->root)+1)]=$f->isLink()?'link:'.readlink($f->getPathname()):($f->isFile()?hash_file('sha256',$f->getPathname()):'dir');ksort($out);return$out;}
}
